import{_ as a,o as e,c as d,a5 as i}from"./chunks/framework.a5no_H3L.js";const g=JSON.parse('{"title":"C# 诊断总览","description":"这套内容面向已经掌握 C# 与 .NET 运行时基础、希望系统排查线上问题的开发者。诊断从「故障现象」出发定位到具体机制，再回到对应原理章节验证根因，而不是凭单点指标下结论。","frontmatter":{},"headers":[],"relativePath":"csharp/07-diagnostics/index.md","filePath":"csharp/07-diagnostics/index.md"}'),s={name:"csharp/07-diagnostics/index.md"};function r(c,t,n,l,o,h){return e(),d("div",null,[...t[0]||(t[0]=[i('<h1 id="c-诊断总览" tabindex="-1" data-src-line="1" data-src-file="csharp/07-diagnostics/index.md">C# 诊断总览 <a class="header-anchor" href="#c-诊断总览" aria-label="Permalink to &quot;C# 诊断总览&quot;">​</a></h1><p data-src-line="3" data-src-file="csharp/07-diagnostics/index.md">这套内容面向已经掌握 C# 与 .NET 运行时基础、希望系统排查线上问题的开发者。诊断从「故障现象」出发定位到具体机制，再回到对应原理章节验证根因，而不是凭单点指标下结论。</p><h2 id="按故障现象定位" tabindex="-1" data-src-line="5" data-src-file="csharp/07-diagnostics/index.md">按故障现象定位 <a class="header-anchor" href="#按故障现象定位" aria-label="Permalink to &quot;按故障现象定位&quot;">​</a></h2><table tabindex="0"><thead data-src-line="7" data-src-file="csharp/07-diagnostics/index.md"><tr data-src-line="7" data-src-file="csharp/07-diagnostics/index.md"><th style="text-align:left;">你看到的现象</th><th style="text-align:left;">先去的入口</th></tr></thead><tbody data-src-line="9" data-src-file="csharp/07-diagnostics/index.md"><tr data-src-line="9" data-src-file="csharp/07-diagnostics/index.md"><td style="text-align:left;">内存持续增长、OOM、GC 频繁</td><td style="text-align:left;"><a href="./01-memory/chapter-01-memory-diagnostics.html">内存诊断</a></td></tr><tr data-src-line="10" data-src-file="csharp/07-diagnostics/index.md"><td style="text-align:left;">堆外/非托管内存增长</td><td style="text-align:left;"><a href="./01-memory/chapter-01-memory-diagnostics.html">内存诊断</a></td></tr><tr data-src-line="11" data-src-file="csharp/07-diagnostics/index.md"><td style="text-align:left;">CPU 利用率高、响应变慢</td><td style="text-align:left;"><a href="./03-performance/chapter-01-cpu-performance.html">CPU 与性能诊断</a></td></tr><tr data-src-line="12" data-src-file="csharp/07-diagnostics/index.md"><td style="text-align:left;">请求卡死、死锁、线程池饥饿</td><td style="text-align:left;"><a href="./02-concurrency/chapter-01-concurrency-diagnostics.html">并发诊断</a></td></tr><tr data-src-line="13" data-src-file="csharp/07-diagnostics/index.md"><td style="text-align:left;">异步方法「没执行完」、<code>async void</code> 崩溃</td><td style="text-align:left;"><a href="./02-concurrency/chapter-01-concurrency-diagnostics.html">并发诊断</a></td></tr><tr data-src-line="14" data-src-file="csharp/07-diagnostics/index.md"><td style="text-align:left;">获取数据库连接超时、慢查询</td><td style="text-align:left;"><a href="./../06-data-access/chapter-03-query-tuning.html">数据访问</a></td></tr></tbody></table><h2 id="诊断工具" tabindex="-1" data-src-line="16" data-src-file="csharp/07-diagnostics/index.md">诊断工具 <a class="header-anchor" href="#诊断工具" aria-label="Permalink to &quot;诊断工具&quot;">​</a></h2><p data-src-line="18" data-src-file="csharp/07-diagnostics/index.md">.NET 提供一套诊断工具，按用途分：</p><table tabindex="0"><thead data-src-line="20" data-src-file="csharp/07-diagnostics/index.md"><tr data-src-line="20" data-src-file="csharp/07-diagnostics/index.md"><th style="text-align:left;">工具</th><th style="text-align:left;">用途</th></tr></thead><tbody data-src-line="22" data-src-file="csharp/07-diagnostics/index.md"><tr data-src-line="22" data-src-file="csharp/07-diagnostics/index.md"><td style="text-align:left;"><code>dotnet-counters</code></td><td style="text-align:left;">实时查看 GC、线程池、分配速率等指标</td></tr><tr data-src-line="23" data-src-file="csharp/07-diagnostics/index.md"><td style="text-align:left;"><code>dotnet-trace</code></td><td style="text-align:left;">采集 CPU、分配、事件追踪</td></tr><tr data-src-line="24" data-src-file="csharp/07-diagnostics/index.md"><td style="text-align:left;"><code>dotnet-dump</code></td><td style="text-align:left;">生成和分析内存转储</td></tr><tr data-src-line="25" data-src-file="csharp/07-diagnostics/index.md"><td style="text-align:left;"><code>dotnet-gcdump</code></td><td style="text-align:left;">采集托管堆快照，定位内存占用</td></tr></tbody></table><p data-src-line="27" data-src-file="csharp/07-diagnostics/index.md">这些工具是诊断的「证据采集」手段。先采集指标和转储，再回到对应原理章节解读证据，而不是先凭经验改配置。</p><h2 id="诊断原则" tabindex="-1" data-src-line="29" data-src-file="csharp/07-diagnostics/index.md">诊断原则 <a class="header-anchor" href="#诊断原则" aria-label="Permalink to &quot;诊断原则&quot;">​</a></h2><ol data-src-line="31" data-src-file="csharp/07-diagnostics/index.md"><li data-src-line="31" data-src-file="csharp/07-diagnostics/index.md"><strong>先现象后根因</strong>：从症状（OOM、CPU 高、卡死）出发，不要先假设属于哪个技术域。</li><li data-src-line="32" data-src-file="csharp/07-diagnostics/index.md"><strong>先证据后结论</strong>：采集指标、转储、日志，确认根因再动手，不要凭单一指标下判断。</li><li data-src-line="33" data-src-file="csharp/07-diagnostics/index.md"><strong>先测量后优化</strong>：用工具量化问题，优化后再量化验证，确认是真实改进。</li><li data-src-line="34" data-src-file="csharp/07-diagnostics/index.md"><strong>机制优先于参数</strong>：理解 GC、线程池、异步的机制，比记住几个配置参数更可靠。</li></ol><h2 id="内容边界" tabindex="-1" data-src-line="36" data-src-file="csharp/07-diagnostics/index.md">内容边界 <a class="header-anchor" href="#内容边界" aria-label="Permalink to &quot;内容边界&quot;">​</a></h2><ul data-src-line="38" data-src-file="csharp/07-diagnostics/index.md"><li data-src-line="38" data-src-file="csharp/07-diagnostics/index.md">本专题负责 .NET 运行时、并发异步、性能的诊断方法与案例。</li><li data-src-line="39" data-src-file="csharp/07-diagnostics/index.md">数据访问的慢查询、连接池问题在<a href="./../06-data-access/chapter-03-query-tuning.html">数据访问</a>专题。</li><li data-src-line="40" data-src-file="csharp/07-diagnostics/index.md">通用可观测性、日志与监控实践由<a href="./../../engineering/">工程</a>专题负责。</li></ul>',12)])])}const x=a(s,[["render",r]]);export{g as __pageData,x as default};
